func (q *Queries) SetBindingConfiguration(ctx context.Context, arg SetBindingConfigurationParams) (Integration, error) {
	row := q.db.QueryRowContext(ctx, setBindingConfiguration,
		arg.ConfigJson,
		arg.Version,
		arg.UpdatedAt,
		arg.ID,
	)
	var i Integration
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Capability,
		&i.Provider,
		&i.ConfigJson,
		&i.Version,
		&i.Managed,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DisplayLabel,
	)
	return i, err
}
